pub(crate) fn report_indented(text: &str) -> String {
    let mut out: String = String::from("");
    let mut first = true;
    for line in text.lines() {
        if !first { out.push_str("\n"); }
        first = false;
        out.push_str("    ");
        out.push_str(line);
    }
    out
}

